// using namespace std;
const ll mod1=998244353,mod2=1e9+7,inf=2e9+7;
const int maxn=1000004,maxm=204;

inline int down(ll x) {return (x%mod1+mod1)%mod1;}

ll n,ans;
std::vector<ll> val[7];
ll sum[7],cnt1,cnt2;
void dfs1(int dep,int num) {
	val[dep].push_back(down(cnt1-num)),++cnt1;
	if(dep==6) return;
	for(rgi i=0;i<10;++i) dfs1(dep+1,num*10+i);
}
const int base=1000000;
void dfs2(int dep,ll num) {
	if(num>n) return;
	if(num*base+999999<=n&&num*base*10>n) {
		for(rgi i=0,l=1,p;i<7;++i,l*=10) {
			ll tmp=down(cnt2-num*l+1);
			p=std::lower_bound(val[i].begin(),val[i].end(),mod1-tmp)-val[i].begin();
			(ans+=tmp*val[i].size()+sum[i]-mod1*(val[i].size()-p))%=mod2;
		}
		cnt2+=cnt1;
	}
	else {
		++cnt2,(ans+=down(cnt2-num))%=mod2;
		for(rgi i=!dep;i<10;++i) dfs2(dep+1,num*10+i);
	}
}
signed main() {
	// freopen("tt.in","r",stdin);
	// freopen("tt.out","w",stdout);
	fin>>n;
	dfs1(0,0);
// cerr<<"OK"<<endl;
	for(rgi i=0;i<7;++i) {
		std::sort(val[i].begin(),val[i].end());
		for(ll x:val[i]) sum[i]+=x;
	}
// cerr<<cnt1<<endl;
	cnt2=-1,dfs2(0,0);
	fout<<ans;
	return 0;
}
